/** A copy of migrations/ holding only the files up to and including `last`. */
async function migrationsUpTo(last: string): Promise<string> {
  const dir = await mkdtemp(join(tmpdir(), 'migrations-'))
  const files = (await readdir('migrations')).filter((f) => f.endsWith('.sql') && f <= last)
  for (const f of files) await copyFile(join('migrations', f), join(dir, f))
  return dir
}

